CREATE TABLE public.growth_outreach_config (id boolean PRIMARY KEY DEFAULT true CHECK (id), agent_id text, calling_enabled boolean NOT NULL DEFAULT false CHECK (calling_enabled = false), founder_user_id uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.growth_outreach_config TO authenticated;
GRANT ALL ON public.growth_outreach_config TO service_role;
ALTER TABLE public.growth_outreach_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_config_admin_read ON public.growth_outreach_config FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.growth_outreach_leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id text UNIQUE NOT NULL, phone text UNIQUE NOT NULL, prospect_name text NOT NULL DEFAULT '', business_name text NOT NULL DEFAULT '', market text NOT NULL DEFAULT '', segment text NOT NULL CHECK (segment IN ('seller','rental_host','buyer','renter','dealer','manufacturer','commissary')), state text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT '', context jsonb NOT NULL DEFAULT '{}'::jsonb, attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0), suppressed boolean NOT NULL DEFAULT false, disposition text NOT NULL DEFAULT 'unavailable', created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.growth_outreach_leads TO authenticated;
GRANT ALL ON public.growth_outreach_leads TO service_role;
ALTER TABLE public.growth_outreach_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_leads_admin_read ON public.growth_outreach_leads FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.growth_outreach_consent (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.growth_outreach_leads(id), channel text NOT NULL CHECK (channel IN ('ai_call','sms_marketing')), status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','verified','rejected')), source text NOT NULL, evidence_text text NOT NULL, accepted_at timestamptz NOT NULL, reviewed_at timestamptz, reviewed_by uuid, revoked_at timestamptz, ai_marketing boolean NOT NULL DEFAULT false, vendibook_named boolean NOT NULL DEFAULT false, dnc_checked_at timestamptz, jurisdiction_approved boolean NOT NULL DEFAULT false, state text NOT NULL, timezone text NOT NULL, window_start integer NOT NULL DEFAULT 10 CHECK (window_start >= 10 AND window_start < 18), window_end integer NOT NULL DEFAULT 18 CHECK (window_end > 10 AND window_end <= 18), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.growth_outreach_consent TO authenticated;
GRANT ALL ON public.growth_outreach_consent TO service_role;
ALTER TABLE public.growth_outreach_consent ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_consent_admin_read ON public.growth_outreach_consent FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.growth_outreach_suppressions (phone text PRIMARY KEY, reason text NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.growth_outreach_suppressions TO authenticated;
GRANT ALL ON public.growth_outreach_suppressions TO service_role;
ALTER TABLE public.growth_outreach_suppressions ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_suppression_admin_read ON public.growth_outreach_suppressions FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.growth_outreach_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), status text NOT NULL DEFAULT 'preview' CHECK (status IN ('preview','audit_approved','blocked','cancelled')), lead_ids uuid[] NOT NULL CHECK (cardinality(lead_ids) BETWEEN 1 AND 10), audit jsonb NOT NULL, created_by uuid NOT NULL, founder_approved_by uuid, founder_approved_at timestamptz, provider_batch_id text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.growth_outreach_batches TO authenticated;
GRANT ALL ON public.growth_outreach_batches TO service_role;
ALTER TABLE public.growth_outreach_batches ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_batches_admin_read ON public.growth_outreach_batches FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.growth_outreach_followups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid NOT NULL REFERENCES public.growth_outreach_leads(id), draft text NOT NULL, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','suppressed')), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.growth_outreach_followups TO authenticated;
GRANT ALL ON public.growth_outreach_followups TO service_role;
ALTER TABLE public.growth_outreach_followups ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_followups_admin_read ON public.growth_outreach_followups FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE TABLE public.growth_outreach_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, action text NOT NULL, record_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.growth_outreach_audit TO authenticated;
GRANT SELECT, INSERT ON public.growth_outreach_audit TO service_role;
ALTER TABLE public.growth_outreach_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY growth_audit_admin_read ON public.growth_outreach_audit FOR SELECT TO authenticated USING (public.has_role(auth.uid(), 'admin'));
COMMENT ON TABLE public.growth_outreach_config IS 'Prepare-only outreach: enabling calling requires a separately reviewed migration and dispatch implementation; no dispatch endpoint exists.';